-- Gnomeregan: creature abilities
-- Almost none of Gnomeregan's trash (the Caverndeep troggs, the irradiated oozes and horrors, the Leprous gnomes, the Mechano-tanks,
-- walkers, sentries and guardians, the Holdout survivors) had AI. Port their abilities from the Cataclysm data, keeping its
-- dungeon flags, and from the classic data where Cataclysm has none (Arcane Nullifier X-21, Holdout Technician, Leprous Assistant,
-- Burning Servant).

SET @ENTRIES := '6206,6211,6218,6219,6220,6222,6223,6224,6225,6226,6227,6230,6232,6233,6234,6235,6329,6392,6407,7079,7603,7738,7800';

UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE FIND_IN_SET(`entry`, @ENTRIES);
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND FIND_IN_SET(`entryorguid`, @ENTRIES);
